import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

type Species = {
  name: string;
  status: string;
};

// FIX marker issue
delete (L.Icon.Default.prototype as any)._getIconUrl;
L.Icon.Default.mergeOptions({
  iconUrl: "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  iconRetinaUrl: "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  shadowUrl: "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
});

export default function MapView({ species }: { species: Species[] }) {
  return (
    <MapContainer center={[20.5937, 78.9629]} zoom={4} style={{ height: "400px" }}>
      <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

      {species.slice(0, 10).map((sp, i) => (
        <Marker key={i} position={[20 + Math.random() * 10, 78 + Math.random() * 10]}>
          <Popup>
            <b>{sp.name}</b><br />
            {sp.status}
          </Popup>
        </Marker>
      ))}
    </MapContainer>
  );
}

import { useEffect, useRef } from "react";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import { species as allSpecies, sightings, type ConservationStatus } from "@/data/mockData";

function getMarkerColor(status: ConservationStatus) {
  switch (status) {
    case "Critically Endangered": return "#e11d48";
    case "Endangered": return "#ea580c";
    case "Vulnerable": return "#eab308";
    case "Near Threatened": return "#16a34a";
  }
}

function createIcon(color: string) {
  return L.divIcon({
    html: `<div style="width:14px;height:14px;border-radius:50%;background:${color};border:2px solid white;box-shadow:0 2px 6px rgba(0,0,0,0.3)"></div>`,
    className: "",
    iconSize: [14, 14],
    iconAnchor: [7, 7],
  });
}

export default function SpeciesMap({ center, className }: { center?: [number, number]; className?: string }) {
  const mapRef = useRef<L.Map | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    const map = L.map(containerRef.current).setView(
      center || [20, 0],
      center ? 5 : 2
    );

    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
    }).addTo(map);

    // Species markers
    allSpecies.forEach((sp) => {
      const color = getMarkerColor(sp.status);
      L.marker([sp.lat, sp.lng], { icon: createIcon(color) })
        .addTo(map)
        .bindPopup(`
          <div style="font-size:14px;min-width:180px">
            <p style="font-weight:bold;font-size:16px;margin:0 0 4px">${sp.name}</p>
            <p style="color:${color};font-weight:600;font-size:12px;margin:0 0 4px">${sp.status}</p>
            <p style="font-size:12px;margin:0 0 4px">${sp.habitat}</p>
            <p style="font-size:12px;margin:0 0 4px">Population: ${sp.population}</p>
            <p style="font-size:12px;font-weight:500;margin:4px 0 0">💡 ${sp.conservationActions[0]}</p>
          </div>
        `);
    });

    // Verified sighting markers
    sightings.filter(s => s.status === "verified").forEach((s) => {
      const sp = allSpecies.find(x => x.name === s.speciesName);
      const color = sp ? getMarkerColor(sp.status) : "#888";
      L.marker([s.lat, s.lng], { icon: createIcon(color) })
        .addTo(map)
        .bindPopup(`
          <div style="font-size:14px;min-width:180px">
            <p style="font-weight:bold;margin:0 0 4px">${s.speciesName} — Sighting</p>
            <p style="font-size:12px;margin:0 0 4px">📅 ${s.date}</p>
            <p style="font-size:12px;margin:0 0 4px">👤 ${s.reporter}</p>
            <p style="font-size:12px;margin:0">${s.notes}</p>
          </div>
        `);
    });

    mapRef.current = map;

    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (center && mapRef.current) {
      mapRef.current.setView(center, 5);
    }
  }, [center]);

  return <div ref={containerRef} className={className || "h-[500px] w-full rounded-lg"} />;
}

import * as React from "react";

import type { ToastActionElement, ToastProps } from "@/components/ui/toast";

const TOAST_LIMIT = 1;
const TOAST_REMOVE_DELAY = 1000000;

type ToasterToast = ToastProps & {
  id: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: ToastActionElement;
};

const actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const;

let count = 0;

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER;
  return count.toString();
}

type ActionType = typeof actionTypes;

type Action =
  | {
      type: ActionType["ADD_TOAST"];
      toast: ToasterToast;
    }
  | {
      type: ActionType["UPDATE_TOAST"];
      toast: Partial<ToasterToast>;
    }
  | {
      type: ActionType["DISMISS_TOAST"];
      toastId?: ToasterToast["id"];
    }
  | {
      type: ActionType["REMOVE_TOAST"];
      toastId?: ToasterToast["id"];
    };

interface State {
  toasts: ToasterToast[];
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return;
  }

  const timeout = setTimeout(() => {
    toastTimeouts.delete(toastId);
    dispatch({
      type: "REMOVE_TOAST",
      toastId: toastId,
    });
  }, TOAST_REMOVE_DELAY);

  toastTimeouts.set(toastId, timeout);
};

export const reducer = (state: State, action: Action): State => {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      };

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) => (t.id === action.toast.id ? { ...t, ...action.toast } : t)),
      };

    case "DISMISS_TOAST": {
      const { toastId } = action;

      // ! Side effects ! - This could be extracted into a dismissToast() action,
      // but I'll keep it here for simplicity
      if (toastId) {
        addToRemoveQueue(toastId);
      } else {
        state.toasts.forEach((toast) => {
          addToRemoveQueue(toast.id);
        });
      }

      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === toastId || toastId === undefined
            ? {
                ...t,
                open: false,
              }
            : t,
        ),
      };
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        };
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      };
  }
};

const listeners: Array<(state: State) => void> = [];

let memoryState: State = { toasts: [] };

function dispatch(action: Action) {
  memoryState = reducer(memoryState, action);
  listeners.forEach((listener) => {
    listener(memoryState);
  });
}

type Toast = Omit<ToasterToast, "id">;

function toast({ ...props }: Toast) {
  const id = genId();

  const update = (props: ToasterToast) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    });
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id });

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss();
      },
    },
  });

  return {
    id: id,
    dismiss,
    update,
  };
}

function useToast() {
  const [state, setState] = React.useState<State>(memoryState);

  React.useEffect(() => {
    listeners.push(setState);
    return () => {
      const index = listeners.indexOf(setState);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }, [state]);

  return {
    ...state,
    toast,
    dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
  };
}

export { useToast, toast };
